-- Vietnam: milestones + English translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'vn-decree-123-2020', id, '2020-12-01', 1, 'https://gdt.gov.vn/wps/portal/english', 0, '[]', NULL, 'none' FROM countries WHERE code = 'VN';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-decree-123-2020', 'en', 'Decree 123/2020/ND-CP establishes Vietnam''s e-invoicing framework', 'The government issued Decree 123/2020/ND-CP, the primary legal framework establishing mandatory e-invoicing for Vietnam, together with implementation guidance that followed in Circular 78/2021/TT-BTC. This decree superseded 2018''s Decree 119/2018/ND-CP, whose original mandate deadline had been postponed, and set the technical and legal foundation -- structured XML invoices, tax-authority verification, and a phased rollout -- for the nationwide mandate that followed in 2022.', '["No action required yet -- this decree sets the legal foundation for the mandate phased in below", "Businesses in the pilot provinces (Hanoi, Ho Chi Minh City) should begin monitoring GDT guidance ahead of the pilot"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'vn-pilot-2021', id, '2021-11-01', 1, 'https://gdt.gov.vn/wps/portal/english', 0, '[]', NULL, 'none' FROM countries WHERE code = 'VN';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-pilot-2021', 'en', 'Pilot phase begins in Hanoi and Ho Chi Minh City', 'The General Department of Taxation (GDT) launched a pilot implementation of Decree 123''s e-invoicing framework across six provinces and cities, including Hanoi and Ho Chi Minh City, ahead of the nationwide mandate. Businesses in the pilot areas began transitioning off paper invoices and testing both of the mandate''s two transmission models -- real-time clearance with a tax-authority code, and same-day reporting without one.', '["Businesses in the six pilot provinces/cities should register with the GDT and choose an integration route now, ahead of the nationwide deadline", "Everywhere else: monitor GDT guidance, since the nationwide mandate follows within months"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'vn-mandate-2022', id, '2022-07-01', 0, 'https://gdt.gov.vn/wps/portal/english', 1, '[{"label": "General Department of Taxation (GDT)", "url": "https://gdt.gov.vn/wps/portal/english"}]', NULL, 'b2b' FROM countries WHERE code = 'VN';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-mandate-2022', 'en', 'E-invoicing becomes mandatory nationwide; paper invoices cease to be valid', 'From this date, structured e-invoices became compulsory for all registered businesses, business households, and individual entrepreneurs under the declared tax method across all of Vietnam, covering domestic B2B, B2C retail, B2G, and export sales. Paper invoices ceased to be legally valid for VAT purposes. Two transmission models coexist: real-time clearance with a GDT-issued code obtained before or at the moment of issuance, or same-day reporting without a code, transmitted to the GDT no later than the day the invoice is delivered.', '["Confirm your business has selected and integrated an e-invoicing solution -- direct API, in-house software, or a certified service provider", "Determine whether your invoices need the tax-authority code (real-time clearance) or fall under the same-day reporting model, and route your systems accordingly", "Retire any remaining paper-invoice processes -- they no longer have legal validity for VAT"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'vn-decree-70-2025', id, '2025-06-01', 0, 'https://gdt.gov.vn/wps/portal/english', 1, '[{"label": "General Department of Taxation (GDT)", "url": "https://gdt.gov.vn/wps/portal/english"}]', NULL, 'b2b' FROM countries WHERE code = 'VN';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-decree-70-2025', 'en', 'Decree 70/2025 expands the mandate to foreign e-commerce suppliers and large business households', 'Decree 70/2025/ND-CP amended Decree 123, bringing business households and individual businesses with annual revenue of VND 1 billion (about USD 38,000) or more into scope for POS cash-register e-invoices connected in real time to the GDT, alongside consumer-facing sectors (shopping malls, supermarkets, restaurants, hotels, passenger transport, and personal services) regardless of revenue size. Foreign e-commerce and digital-service suppliers without a permanent Vietnamese establishment can now register to issue Vietnamese VAT invoices directly, and the decree standardized invoice-issuance timing rules across transaction types (goods, services, exports, utilities).', '["Business households and individual businesses above the VND 1 billion threshold: register a POS system connected to the GDT if you haven''t already", "Consumer-facing businesses (retail, hospitality, transport, personal services): confirm POS e-invoicing compliance regardless of your revenue level", "Foreign digital-service suppliers: evaluate registering for Vietnamese VAT invoicing directly under the new provision"]');
